import { ChangeDetectorRef, Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { UploadService } from '../../../services/upload/upload.service';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { MatSelectModule } from '@angular/material/select';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatFormFieldModule } from '@angular/material/form-field';
import { ScrollingModule } from '@angular/cdk/scrolling';
import { CommonModule } from '@angular/common';
import { SkeletonComponent } from '../../../../shared/components/skeleton/skeleton.component';
import { bundleMDL, fileUploadMDL, sectionDetailMDL, selectedfileMDL } from '../../../interfaces/upload.interface';
import { FileStorageService } from '../../../services/upload/file-storage/file-storage.service';
import { BytesPipe } from '../../../../shared/pips/bytes/bytes.pipe';
import { NgxFileDropEntry, NgxFileDropModule } from 'ngx-file-drop';
import { FileSelectionService } from '../../../services/upload/file-selection/file-selection.service';
import { MatDialog, MatDialogModule } from '@angular/material/dialog';
import { FileexplorerComponent } from '../../../../shared/components/myfiles/fileexplorer/fileexplorer.component';
import { CheckDuplicacyService } from '../../../services/upload/check-duplicacy/check-duplicacy.service';
import { UploadManagementService } from '../../../services/upload/upload-management/upload-management.service';
import { MatMenuModule } from '@angular/material/menu';
import { environment } from '../../../../../environments/environment';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { FormsModule } from '@angular/forms';
import { MatTooltipModule } from '@angular/material/tooltip';

@Component({
  selector: 'choosenfiles',
  standalone: true,
  imports: [MatMenuModule, IconComponent, MatSelectModule, FormsModule, ButtonComponent, MatCheckboxModule, MatFormFieldModule, MatTooltipModule,
    ScrollingModule, CommonModule, SkeletonComponent, BytesPipe, NgxFileDropModule, MatDialogModule],
  templateUrl: './choosenfiles.component.html',
  styleUrls: ['./choosenfiles.component.scss']
})
export class ChoosenfilesComponent implements OnInit {
  @Input() isUser: boolean = false;
  @Input() nSectionid: string;
  public items: selectedfileMDL[] = []
  public isLoading: boolean = true;
  public lastOpenedNode: selectedfileMDL;
  public isDragging: boolean = false;
  public isFileSelecting: boolean = false;
  public isUploading: boolean = false;
  public sectionDetail: sectionDetailMDL;
  public bundle: bundleMDL;
  public cFilename: string = '';
  public duplicateFiles: number[] = [];
  // private dragInteravl: any;
  public isDuplicacychecking: boolean = false;
  public isDuplicate: boolean = false;
  public updatedResponce: number[][] = [];
  public finalUpload: fileUploadMDL[] = [];
  public canUpload: boolean = true;
  private docIconPath: string = environment.iconpath_doc;
  public nCaseid: string = null;
  private resetTime: any;
  @Output() dataRecieved = new EventEmitter<any>();
  isAllconvert: boolean = true;
  convertType: string = 'N';
  bIsocr: boolean = false;
  nOcrtype: number = 0;
  private temperoryUploadSession: any;
  showuplicateOnly: boolean = false;
  constructor(public dialog: MatDialog, private selection: FileSelectionService,
    public store: FileStorageService, private cd: ChangeDetectorRef, private checkfile: CheckDuplicacyService,
    private uploadManage: UploadManagementService, private tst: TostbarService
  ) { }

  async ngOnInit(): Promise<void> {
    this.items = await this.store.getSelectedFileStorageByLevel(0);
    this.isLoading = false;

    this.initDetail();
  }

  async initDetail(value?: { nBundleid: string, nSectionid: string }) {

    this.sectionDetail = await this.store.getSectionDetail(value ? value.nSectionid : null);
    this.bundle = await this.store.getBundleDetail(value ? value.nBundleid : null);
    this.nCaseid = await this.store.getCaseId();
    this.getChoosenBundle();
  }

  getChoosenBundle() {
    this.cFilename = this.bundle.cBundlename ? this.bundle.cBundlename : (this.sectionDetail.cFolder ? this.sectionDetail.cFolder : 'No Bundle Selected')
  }

  trackByFn(index: number, item: selectedfileMDL) {
    return item.id;
  }

  async bindNextData(node: selectedfileMDL, index: number, checkSub?: boolean): Promise<any> {
    if (node.isFolder) {
      if (node.isExpanded) {
        node.isExpanded = false;
        let nextIndex = index + 1;
        while (nextIndex < this.items.length && this.items[nextIndex].level > node.level) {
          nextIndex++;
        }
        this.items.splice(index + 1, nextIndex - index - 1);
        this.items = [...this.items];
        this.cd.detectChanges();
        return (nextIndex - index - 1);

      }
      if (!checkSub) {
        const openedNode: selectedfileMDL = this.items.find(a => a.isExpanded && a.level == node.level);
        if (openedNode) {
          const rmVindex = this.items.indexOf(openedNode);
          const removedLines = await this.bindNextData(openedNode, rmVindex, true);
          if (index > rmVindex) {
            index = (index - removedLines);
          }
        }
      }
      node.isExpanded = true;
      this.lastOpenedNode = node;
      const childItems: selectedfileMDL[] = await this.store.getSelectedFileStorageByLevel(node.id);
      if (childItems.length > 0) {
        childItems.map(a => a.isExpanded = false);
        this.items.splice(index + 1, 0, ...childItems);
        this.items = [...this.items];
        this.cd.detectChanges();
      } else {
        // node.isExpanded = false;
      }
    }
    return true;
  }

  async onFileDrop(event: NgxFileDropEntry[]) {
    this.isFileSelecting = true;
    let listData: selectedfileMDL[] = await this.selection.fetchFiles(event, this.lastOpenedNode);
    this.isFileSelecting = false;
    this.isDragging = false;
    if (listData.length) {
      this.store.setSelectedFileStorage(listData)
      try {
        const OpenedIndex = this.items.findIndex(a => a.id == this.lastOpenedNode.id);
        if (this.lastOpenedNode) {
          await this.bindNextData(this.lastOpenedNode, OpenedIndex);
          await this.bindNextData(this.lastOpenedNode, OpenedIndex);
        } else {
          this.items = await this.store.getSelectedFileStorageByLevel(0);
        }
      } catch (error) {
        this.items = await this.store.getSelectedFileStorageByLevel(0);
      }
    }
  }

  DragTo(val: boolean) {
    this.isDragging = val;
  }

  async chooseLocation() {
    const dialogRef = this.dialog.open(FileexplorerComponent, {
      width: '90vw',
      height: '89vh',
      // data: {nCaseid:this.nCaseid}
    });
    dialogRef.componentInstance.nCaseid = this.nCaseid;
    dialogRef.componentInstance.isChooser = true;
    dialogRef.componentInstance.isDownload = true;
    dialogRef.componentInstance.isUser = this.isUser;
    dialogRef.componentInstance.nSectionid = this.nSectionid;
    dialogRef.afterClosed().subscribe(result => {
      if (dialogRef.componentInstance.isSave) {
        this.initDetail({ nBundleid: dialogRef.componentInstance.nBundleid, nSectionid: dialogRef.componentInstance.activeSection.nSectionid });
        // use result if dialog was closed using [mat-dialog-close]
      }
    });
    setTimeout(() => {
      debugger
      dialogRef.componentInstance.cs.callFunction({ event: 'SHOW-FOLDER', nBundleid: this.bundle.nBundleid });
    }, 200);
  }

  async RemoveNode(node: selectedfileMDL, index: number) {

    let selectedFiles: selectedfileMDL[] = await this.store.getSelectedFileStorage()
    if (node.isFolder) {
      const markForRemoval = (parentId: number, list: selectedfileMDL[]) => {
        return list.reduce((acc, item) => {
          if (item.parentId === parentId) {
            if (item.isFolder) {
              acc.push(...markForRemoval(item.id, list));
            }
            acc.push(item.id);
          }
          return acc;
        }, []);
      };
      const idsToRemove = markForRemoval(node.id, selectedFiles);
      idsToRemove.push(node.id);
      this.items = this.items.filter(item => !idsToRemove.includes(item.id));
      selectedFiles = selectedFiles.filter(item => !idsToRemove.includes(item.id));
      this.items = [...this.items];
      await this.store.setSelectedFileStorage(selectedFiles);
    } else {
      this.items.splice(index, 1);
      this.items = [...this.items];
      selectedFiles = selectedFiles.filter(a => a.id != node.id);
      await this.store.setSelectedFileStorage(selectedFiles);
    }

    this.refreshDulicateData(node)

    this.cd.detectChanges();
  }

  async refreshDulicateData(data: selectedfileMDL) {
    let ind = this.duplicateFiles.findIndex(a => a[0] == data.id);
    if (ind != -1) {
      this.duplicateFiles.splice(ind, 1);
    }
    if (!this.duplicateFiles.length) {
      this.isDuplicate = false;
    }

  }


  reinitData() {
    this.temperoryUploadSession = null;
    this.duplicateFiles = [];
    this.isDuplicate = false;
    this.canUpload = true;
    this.isUploading = false;
  }





  bindIcon(node) {
    try {
      const fileType = node.file.name.split('.').pop().toLowerCase();
      return `${this.docIconPath}${fileType}.svg`;
    } catch (error) {
      return `${this.docIconPath}other.svg`;
    }
  }

  removeAll() {
    this.temperoryUploadSession = null;
    this.items = [];
    this.reinitData();
    this.store.setSelectedFileStorage([]);
  }

  allConvertChange(event: any): void {
    this.store.filetypes.filter(item => !item.isDisabled).map(a => a.isConvert = event.checked);
    this.cd.detectChanges();
    return;
  }

  async Upload() {

    this.reinitData();
    this.isUploading = true;
    this.canUpload = false;
    this.isDuplicacychecking = true;
    this.temperoryUploadSession = await this.checkfile.checkDuplicacy();
    if (this.temperoryUploadSession) {
      this.updatedResponce = this.temperoryUploadSession.finalData;
      this.isDuplicacychecking = false;
      // return;
      if (this.updatedResponce) {
        this.duplicateFiles = await this.checkfile.isDuplicated(this.updatedResponce);
        this.isUploading = false;
        if (this.duplicateFiles.length) {
          this.isDuplicate = true;

          const matched = this.duplicateFiles.map(a => a[0]);

          this.items.map(a => a.isDuplicated = matched.includes(a.id));

        } else {




          this.uploadMerging('U');
        }
      } else {
        this.isUploading = false;
        this.tst.openSnackBar('Failed to check duplicacy', 'E');
        // dulicacy check failed;
      }
    } else {
      this.isUploading = false;
      this.tst.openSnackBar('Failed to check duplicacy', 'E');
    }

  }


  checkConversion() {
    for (let item of this.finalUpload) {
      let type = this.store.getFileType(item.file.name)
      item.bIsconvert = this.store.filetypes.find(a => a.type == type).isConvert;
      item.converttype = this.convertType;
      item.bIsocr = this.bIsocr;
      item.nOcrtype = this.nOcrtype;
    }
  }



  async uploadMerging(flag) {

    this.finalUpload = await this.checkfile.mergeresult(this.updatedResponce, flag, this.temperoryUploadSession.nUPid);

    this.checkConversion();

    if (this.finalUpload.length) {
      let res = this.uploadManage.startUpload(this.finalUpload, this.temperoryUploadSession.nUPid, this.temperoryUploadSession.cUnicid);
      if (res) {
        this.resetDelay();
      }
    } else {
      this.tst.openSnackBar('No file for upload', 'E')
      // upload failed
    }

  }

  resetDelay() {
    clearTimeout(this.resetTime);
    this.resetTime = setTimeout(() => {
      this.wipeOut();
    }, 3000);
  }

  wipeOut() {
    try {
      this.removeAll();
    } catch (error) {
      console.log('error', error);
    }
    this.dataRecieved.emit('RESET-UI');
    this.store.uploading = false;
  }


}